// Every recolourable part in public/models/f56.glb (node extras.part).
// Generated by scripts/build-model.mjs — keep the two in sync.

export const PART_GROUPS = {
  body: [
    "hood", "bumper_f", "bumper_r", "tailgate",
    "fender_l", "fender_r", "door_l", "door_r", "quarter_l", "quarter_r",
  ],
  contrast: ["roof", "spoiler", "spoiler_lip", "mirror_cap_l", "mirror_cap_r"],
  glass: ["sunroof"],
  chrome: [
    "chrome_grille_surround", "chrome_window_trim", "chrome_cowl",
    "chrome_side_scuttle_l", "chrome_side_scuttle_r",
    "chrome_door_handle_l", "chrome_door_handle_r",
    "chrome_taillight_ring_l", "chrome_taillight_ring_r",
    "chrome_fuel_cap", "chrome_exhaust",
  ],
  accents: ["hood_scoop", "grille_bar", "headlight_drl_l", "headlight_drl_r", "headlight_ring_lower_l", "headlight_ring_lower_r"],
  wheels: ["wheels", "callipers"],
} as const;

export type PartGroup = keyof typeof PART_GROUPS;
export type PartId = (typeof PART_GROUPS)[PartGroup][number];

export const ALL_PARTS = Object.values(PART_GROUPS).flat() as PartId[];

/** Shorthand selectors usable in event data instead of listing every part. */
export const PART_ALIASES: Record<string, readonly PartId[]> = {
  "@body": PART_GROUPS.body,
  "@chrome": PART_GROUPS.chrome.filter((p) => p !== "chrome_exhaust"),
  "@mirror_caps": ["mirror_cap_l", "mirror_cap_r"],
  "@doors": ["door_l", "door_r"],
  "@fenders": ["fender_l", "fender_r"],
  "@drl": ["headlight_drl_l", "headlight_drl_r"],
  "@headlight_ring_lower": ["headlight_ring_lower_l", "headlight_ring_lower_r"],
};

const LABELS: Partial<Record<PartId, string>> = {
  bumper_f: "Front bumper",
  bumper_r: "Rear bumper",
  mirror_cap_l: "Mirror cap (left)",
  mirror_cap_r: "Mirror cap (right)",
  grille_bar: "Grille bar",
  sunroof: "Panorama glass roof",
  spoiler_lip: "Spoiler lip (underside trim)",
  chrome_grille_surround: "Grille surround",
  chrome_window_trim: "Window line trim",
  chrome_cowl: "Cowl trim",
  chrome_fuel_cap: "Fuel cap",
  chrome_exhaust: "Exhaust tips",
};

export function partLabel(id: PartId): string {
  if (LABELS[id]) return LABELS[id]!;
  const side = id.endsWith("_l") ? " (left)" : id.endsWith("_r") ? " (right)" : "";
  const base = id.replace(/^chrome_/, "").replace(/_[lr]$/, "").replace(/_/g, " ");
  return base.charAt(0).toUpperCase() + base.slice(1) + side;
}
